questions.solution:
const secreto = 7;
let intento;
let intentos = 0;
do {
  intento = Number(prompt("Adivina el número:"));
  intentos++;
  if (intento < secreto) {
    console.log("Es mayor");
  } else if (intento > secreto) {
    console.log("Es menor");
  }
} while (intento !== secreto);
console.log("¡Adivinaste en " + intentos + " intentos!");

